    var country = timeZones.countries[countryName];
    var single = own(timeZones.single, country);
    if (single) return timeZones.zones[single];

    var locality = place.slice(countryName.length);
    var regions = own(timeZones.regions, country);
    var regionName = placePrefix(regions, locality, location);
    if (!regionName) return timeZones.zones[own(own(timeZones.cities, country), locality)] || '';

    var region = regions[regionName];
    var local = own(timeZones.localCities, country + '.' + region[0]);
